import { memo } from 'react';

import { Cover } from 'components';
import { useVolumePagesKpi } from 'pages/pillars/ValueCreation/VolumePages/contexts';
import { CountrySlideWrapper } from 'pages/pillars/ValueCreation/VolumePages/tabs/Global/components/CountrySlideWrapper';
import { COUNTRIES } from 'pages/pillars/ValueCreation/VolumePages/tabs/Global/constants/countries';
import { volumePagePrefixedTestId } from 'pages/pillars/ValueCreation/VolumePages/utils';
import { StyledExportPageSection } from 'shared/Styles/exportPages.styles';

import {
  pageSections,
  SUMMARY_COUNTRY_SECTION_MAP,
  SUMMARY_MUST_WIN_COUNTRIES,
} from '../../constants';
import { SummaryMustWinMarketsSectionProps } from './types';

export const SummaryMustWinMarketsSection = memo(
  ({
    getPageByName,
    dataTestId,
    period,
  }: SummaryMustWinMarketsSectionProps) => {
    const { kpi } = useVolumePagesKpi();

    return (
      <>
        <StyledExportPageSection
          data-page-name={pageSections.mustWinMarketsCover}
        >
          <Cover
            category="One Way Reports"
            name="Must Win Markets"
            centerText
            centerLogo
            showLogo
            showLink={false}
            dataTestId={volumePagePrefixedTestId(
              dataTestId,
              'summary-must-win-markets-cover',
            )}
          />
        </StyledExportPageSection>

        {SUMMARY_MUST_WIN_COUNTRIES.map((countryCode) => {
          const config = COUNTRIES[countryCode];

          return (
            <CountrySlideWrapper
              key={countryCode}
              countryCode={countryCode}
              config={config}
              subFilters={{ ...config.subFilters, kpi }}
              period={period}
              getPageByName={getPageByName}
              dataTestId={dataTestId}
              hideBrandsBreakdown
              sectionOverride={SUMMARY_COUNTRY_SECTION_MAP[countryCode]}
            />
          );
        })}
      </>
    );
  },
);

SummaryMustWinMarketsSection.displayName = 'SummaryMustWinMarketsSection';
